#!/usr/bin/env bash
# generated by rcm-store-connect — release_golive.sh: rcm role `golive`: plan (read-only) or release an approved build.
#
#   Runs in the workspace rcm made from a git_ref (repository root). Inputs arrive as environment variables:
#     RCM_INPUT_MODE=plan|release             default plan — the preset default is plan and must stay so
#     RCM_INPUT_BUILD_NAME=X.Y.Z              the version to put live (iOS, and Android unless the next one is set)
#     RCM_INPUT_BUILD_NAME_ANDROID=X.Y.Z      the Android version name when it differs (empty = BUILD_NAME)
#     RCM_INPUT_CONFIRM_BUILD_NUMBER=N        release: the build number a person typed; must equal the approved build
#     RCM_INPUT_PLATFORM=ios|android|both     default both
#   Secrets: the folder rcm hands over in ${{secrets_env}}. Never printed.
#
#   Writes (build/.rcm-release/, RELEASE_WORK overrides):
#     golive-plan.json   mode=plan, however the run ends:
#                        { schema, build_name, measured_at, plan_verdict ok|blocked, reasons[],
#                          platforms { ios|android: { approved, approved_build, raw_state } } }
#     golive.json        mode=release, however the run ends:
#                        { schema, build_name, finished_at,
#                          platforms { ios: { result requested|released|pending|failed, raw_state },
#                                      android: { result published|pending|needs_login|failed, raw_state } } }
#   Exit codes (docs/release-contract.md §2):
#     plan     0 the stores were read (approved or not: that is in platforms.<p>.approved, never in the exit code)
#              1 a store could not be read · 2 environment / usage
#     release  0 done (the store says it is live) · 75 not yet — ONLY for work left after approval (a release
#              still processing, a sign-in to renew, a publish to confirm) · 1 failed · 2 blocked (a chosen
#              platform is not approved; also environment / usage) · 3 the typed build number is not the approved one
#   Markers: ::rcm::steps::4 · ::rcm::step::… · ::rcm::action::login::<note> when a person must sign in ·
#            ::rcm::summary::… last. The note is shown without a token: never put an account or e-mail in it.
#
#   Safety built in — keep it:
#     · mode=plan never calls store_ios_release() or store_android_publish(); it only reads.
#     · mode=release reads the stores first and calls nothing unless EVERY chosen platform is approved and the
#       typed number equals its approved build. A build that is not approved exits 2, never 75: waiting for an
#       approval with 75 would turn this role into the release-on-approval that rcm forbids.
#     · A lost sign-in: print the ::rcm::action::login:: marker and exit 75 at once — never wait for the sign-in
#       here. The next attempt checks again; a job that sits waiting hides behind the server's needs_action
#       reason, which then masks a stuck or overdue job.
#     · Nothing here runs on its own. rcm runs mode=release only when a person asked for it with the version,
#       the build number and a time.
#
#   --selftest   shims replace the store; proves: plan exits 0 with Android not approved (approved=false in the
#                file), plan with a store unreadable -> 1, release not approved -> 2 with no release call, a wrong
#                number -> 3, a lost sign-in -> action marker + 75, a live build -> 0 without a call.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; SELF="$HERE/$(basename "${BASH_SOURCE[0]}")"; ROOT="$(cd "$HERE/../.." && pwd)"; cd "$ROOT"

CONTRACT="${RCM_CONTRACT_PY:-$HERE/rcm_contract.py}"
WORK="${RELEASE_WORK:-$ROOT/build/.rcm-release}"
SECRETS_ENV="{{secrets_env}}"
# 안 채워진 템플릿(`{{secrets_env}}` 그대로)도 셀프테스트로 돌아야 한다 — bash 5 는 이름이
# 아닌 것의 간접 확장을 거부한다. 이름이 아니면 셀프테스트용 이름을 쓴다(채운 사본은 그대로).
case "$SECRETS_ENV" in ""|[0-9]*|*[!A-Za-z0-9_]*) SECRETS_ENV=RCM_TEMPLATE_SECRETS_DIR;; esac
SECRETS_DIR="${!SECRETS_ENV:-}"
SHIM="${RELEASE_SHIM:-}"                                 # selftest only: any value turns the shims on
SHIM_CALLS="${RELEASE_SHIM_CALLS:-/dev/null}"
MODE="${RCM_INPUT_MODE:-plan}"
BUILD_NAME="${RCM_INPUT_BUILD_NAME:-}"
BUILD_NAME_ANDROID="${RCM_INPUT_BUILD_NAME_ANDROID:-}"
CONFIRM="${RCM_INPUT_CONFIRM_BUILD_NUMBER:-}"
PLATFORM="${RCM_INPUT_PLATFORM:-both}"
WRITTEN=0
STARTED=0   # 사용법 · 환경 검사를 지난 뒤에만 1 — 그 전에 끝나면 golive.json 을 남기지 않는다

usage() {
  echo "usage: RCM_INPUT_BUILD_NAME=X.Y.Z [RCM_INPUT_MODE=plan|release] [RCM_INPUT_PLATFORM=ios|android|both]" >&2
  echo "       [RCM_INPUT_BUILD_NAME_ANDROID=X.Y.Z] [RCM_INPUT_CONFIRM_BUILD_NUMBER=N] release_golive.sh | release_golive.sh --selftest" >&2
  exit 2
}

# ── project hooks — the only places that talk to a store ─────────────────────────────────────────────
# store_approval PLATFORM VERSION_NAME: read-only. Print ONE JSON object:
#   { "approved": true|false,          true once review approved this version (also while / after it goes live)
#     "approved_build": 185 | null,    the approved build number (iOS build, Android version code)
#     "raw_state": "PENDING_DEVELOPER_RELEASE",   the store's own word
#     "stage": "waiting|in_progress|live" }       approved only: nothing done yet · release requested or
#                                                 publishing, not live yet · live (read from the store API)
#   Exit non-zero when the store cannot be read.
#   Android has no API state between «approved, held» and PUBLISHED, so after publish was pressed, answer
#   in_progress until the API says PUBLISHED. The project must remember that it pressed publish, or make the
#   hook idempotent; otherwise the next attempt sees «waiting», presses publish again, finds no button and
#   exits 1, which ends the retry chain.
store_approval() {
  if [ -n "$SHIM" ]; then shim_store_approval "$@"; return $?; fi
  # TODO(project): iOS — the App Store version $2: appStoreState (PENDING_DEVELOPER_RELEASE = approved, waiting;
  #   PROCESSING_FOR_DISTRIBUTION = in_progress; READY_FOR_DISTRIBUTION = live) and its build. Android — the
  #   production track: RELEASE_LIFECYCLE_STATE_APPROVED_NOT_PUBLISHED = approved, waiting (in_progress once this
  #   project pressed publish for that version code — remember it next to the secrets); PUBLISHED = live.
  #   Credentials in "$SECRETS_DIR". Read-only. Delete the two lines below when done.
  echo "store_approval() is not implemented — fill the TODO(project) block in scripts/release/release_golive.sh" >&2
  return 1
}
# store_ios_release VERSION_NAME BUILD: ask App Store Connect to release the approved version. Print ONE JSON
#   object { "result": "requested|released|pending", "raw_state": "…" }. Exit non-zero = failed.
store_ios_release() {
  if [ -n "$SHIM" ]; then shim_store_ios_release "$@"; return $?; fi
  # TODO(project): POST /v1/appStoreVersionReleaseRequests for the version $1 (build $2) with the key in
  #   "$SECRETS_DIR". Delete the two lines below when done.
  echo "store_ios_release() is not implemented — fill the TODO(project) block in scripts/release/release_golive.sh" >&2
  return 1
}
# store_android_publish VERSION_NAME VERSION_CODE: publish the release that managed publishing holds. Play has no
#   API for it, so this is the project's browser automation on the build machine (its own Chrome profile, kept
#   next to the secrets, never in the workspace). Check the sign-in first. Print ONE JSON object
#   { "result": "published|pending|needs_login", "raw_state": "…" }. Exit non-zero = failed (leave a screenshot
#   when the button is not where it should be). Whether it went live is read back through the API, not the screen.
store_android_publish() {
  if [ -n "$SHIM" ]; then shim_store_android_publish "$@"; return $?; fi
  # TODO(project): open the dedicated Chrome profile, confirm Play Console is signed in (else print
  #   {"result": "needs_login", …} and exit 0 at once — do not wait for a person), press publish for version
  #   code $2, record that it was pressed, then read the track back.
  #   Delete the two lines below when done.
  echo "store_android_publish() is not implemented — fill the TODO(project) block in scripts/release/release_golive.sh" >&2
  return 1
}

# ── selftest shims ───────────────────────────────────────────────────────────────────────────────────
# RELEASE_SHIM_IOS · RELEASE_SHIM_ANDROID = waiting | in_review | in_progress | live | unreadable
# RELEASE_SHIM_IOS_ACTION = requested | fail · RELEASE_SHIM_ANDROID_ACTION = published | pending | needs_login | fail
# RELEASE_SHIM_ANDROID_BUILD = the approved version code (default 185)
shim_store_approval() {
  echo "store_approval '$1' '$2'" >>"$SHIM_CALLS"
  local state build=185
  if [ "$1" = ios ]; then state="${RELEASE_SHIM_IOS:-waiting}"; else state="${RELEASE_SHIM_ANDROID:-waiting}"; build="${RELEASE_SHIM_ANDROID_BUILD:-185}"; fi
  case "$state" in
    waiting|in_progress|live) echo "{\"approved\": true, \"approved_build\": $build, \"raw_state\": \"SHIM_${state}\", \"stage\": \"$state\"}";;
    in_review)  echo '{"approved": false, "approved_build": null, "raw_state": "SHIM_IN_REVIEW"}';;
    unreadable) return 7;;
    *) echo "unknown shim state $state" >&2; return 9;;
  esac
}
shim_store_ios_release() {
  echo "store_ios_release '$1' '$2'" >>"$SHIM_CALLS"
  case "${RELEASE_SHIM_IOS_ACTION:-requested}" in
    requested) echo '{"result": "requested", "raw_state": "SHIM_PENDING_DEVELOPER_RELEASE"}';;
    *) return 1;;
  esac
}
shim_store_android_publish() {
  echo "store_android_publish '$1' '$2'" >>"$SHIM_CALLS"
  case "${RELEASE_SHIM_ANDROID_ACTION:-published}" in
    published|pending|needs_login) echo "{\"result\": \"${RELEASE_SHIM_ANDROID_ACTION:-published}\", \"raw_state\": \"SHIM_APPROVED_NOT_PUBLISHED\"}";;
    *) return 1;;
  esac
}

# ── contract plumbing ────────────────────────────────────────────────────────────────────────────────
step()     { echo "::rcm::step::$1"; }
step_end() { echo "::rcm::step-end::$1"; }
finish()   { echo "::rcm::summary::$1"; exit "$2"; }
jget() { python3 -c 'import json,sys; v=json.load(open(sys.argv[1])).get(sys.argv[2]); print("" if v is None else (json.dumps(v) if isinstance(v,(bool,dict,list)) else v))' "$1" "$2"; }
name_for() { if [ "$1" = android ] && [ -n "$BUILD_NAME_ANDROID" ]; then echo "$BUILD_NAME_ANDROID"; else echo "$BUILD_NAME"; fi; }
platforms() { case "$PLATFORM" in both) echo "ios android";; *) echo "$PLATFORM";; esac; }

# 플랫폼마다 $WORK/golive-<p>.part.json 하나 — 마지막에 한 문서로 합친다.
part() {  # $1 platform · $2 JSON object
  printf '%s\n' "$2" >"$WORK/golive-$1.part.json"
}
merged_parts() {  # prints {"ios": …, "android": …} for the parts that exist
  python3 - "$WORK" $(platforms) <<'PY'
import json, os, sys
work, plats = sys.argv[1], sys.argv[2:]
out = {}
for p in plats:
    path = os.path.join(work, f"golive-{p}.part.json")
    if os.path.isfile(path):
        out[p] = json.load(open(path))
print(json.dumps(out))
PY
}
write_plan_doc() {  # $1 verdict · rest reasons
  local verdict="$1"; shift
  local args=(write golive-plan --out "$WORK/golive-plan.json" --build-name "$BUILD_NAME" --platforms-json "$(merged_parts)" --plan-verdict "$verdict")
  local r; for r in "$@"; do args+=(--reason "$r"); done
  python3 "$CONTRACT" "${args[@]}" && WRITTEN=1
}
write_golive_doc() {  # $1 exit code
  python3 "$CONTRACT" write golive --out "$WORK/golive.json" --build-name "$BUILD_NAME" \
    --platforms-json "$(merged_parts)" --extra-json "{\"exit_code\": $1, \"platform\": \"$PLATFORM\"}" && WRITTEN=1
}
on_exit() {  # 마지막 안전망 — release 는 어떤 경로로 끝나든 golive.json 이 남는다
  local rc=$? p
  [ "$WRITTEN" = 1 ] && return 0
  [ "$MODE" = release ] && [ "$STARTED" = 1 ] || return 0
  for p in $(platforms); do
    [ -f "$WORK/golive-$p.part.json" ] || part "$p" '{"result": "failed", "raw_state": null, "reason": "aborted"}'
  done
  write_golive_doc "$rc" >/dev/null 2>&1 || true
}
trap on_exit EXIT

read_approvals() {  # 고른 플랫폼마다 승인을 읽어 $WORK/approval-<p>.json. 못 읽은 플랫폼 이름을 출력한다
  local p rc
  for p in $(platforms); do
    rc=0; store_approval "$p" "$(name_for "$p")" >"$WORK/approval-$p.json" 2>"$WORK/approval-$p.err" || rc=$?
    if [ "$rc" != 0 ] || ! python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); assert isinstance(d.get("approved"), bool)' "$WORK/approval-$p.json" 2>/dev/null; then
      rm -f "$WORK/approval-$p.json"; echo "$p"
    fi
  done
}

do_plan() {
  local p unreadable reasons=() approved
  step "read stores"
  unreadable="$(read_approvals)"
  step_end ok
  step "golive-plan.json"
  for p in $(platforms); do
    if [ ! -f "$WORK/approval-$p.json" ]; then
      part "$p" '{"approved": false, "approved_build": null, "raw_state": null}'
      reasons+=("${p}_unreadable"); continue
    fi
    part "$p" "$(python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); print(json.dumps({"approved": d["approved"], "approved_build": d.get("approved_build"), "raw_state": d.get("raw_state")}))' "$WORK/approval-$p.json")"
    approved="$(jget "$WORK/approval-$p.json" approved)"
    [ "$approved" = true ] || reasons+=("${p}_not_approved")
  done
  if [ "${#reasons[@]}" = 0 ]; then write_plan_doc ok; else write_plan_doc blocked "${reasons[@]}"; fi || {
    step_end fail; finish "failed — store_approval() output violates the contract (see log)" 1; }
  step_end ok
  step "done"; step_end ok
  if [ -n "$unreadable" ]; then
    finish "plan — could not read: $(echo $unreadable) (golive-plan.json written; nothing released)" 1
  fi
  finish "plan — $([ "${#reasons[@]}" = 0 ] && echo "approved: $(platforms | tr ' ' '+')" || echo "${reasons[*]}") (read-only; nothing released)" 0
}

do_release() {
  local p unreadable state build approved stage rc res results=() overall=0
  step "read stores"
  unreadable="$(read_approvals)"
  if [ -n "$unreadable" ]; then
    for p in $unreadable; do part "$p" '{"result": "failed", "raw_state": null, "reason": "unreadable"}'; done
    for p in $(platforms); do [ -f "$WORK/golive-$p.part.json" ] || part "$p" '{"result": "failed", "raw_state": null, "reason": "not_attempted"}'; done
    step_end fail; write_golive_doc 1
    finish "failed — could not read: $(echo $unreadable); nothing released" 1
  fi
  step_end ok

  # 출시 훅은 고른 플랫폼이 **모두** 승인됐고 번호가 맞을 때만 부른다 — 하나라도 아니면 아무것도 안 한다.
  step "check approval + build number"
  local blocked="" mismatch=""
  for p in $(platforms); do
    approved="$(jget "$WORK/approval-$p.json" approved)"; build="$(jget "$WORK/approval-$p.json" approved_build)"
    state="$(jget "$WORK/approval-$p.json" raw_state)"
    if [ "$approved" != true ]; then blocked="$blocked $p"; part "$p" "{\"result\": \"failed\", \"raw_state\": $(python3 -c 'import json,sys; print(json.dumps(sys.argv[1] or None))' "$state"), \"reason\": \"not_approved\"}"
    elif [ "$build" != "$CONFIRM" ]; then mismatch="$mismatch $p"; part "$p" "{\"result\": \"failed\", \"raw_state\": $(python3 -c 'import json,sys; print(json.dumps(sys.argv[1] or None))' "$state"), \"reason\": \"build_number_mismatch\", \"approved_build\": ${build:-null}}"
    fi
  done
  if [ -n "$blocked" ] || [ -n "$mismatch" ]; then
    for p in $(platforms); do [ -f "$WORK/golive-$p.part.json" ] || part "$p" '{"result": "failed", "raw_state": null, "reason": "not_attempted"}'; done
    step_end fail
    if [ -n "$blocked" ]; then
      write_golive_doc 2
      finish "blocked — not approved:$blocked; nothing released (exit 2, not 75: rcm never waits for an approval)" 2
    fi
    write_golive_doc 3
    finish "build number mismatch —$mismatch approved build is not $CONFIRM; nothing released" 3
  fi
  step_end ok

  step "release"
  for p in $(platforms); do
    stage="$(jget "$WORK/approval-$p.json" stage)"; state="$(jget "$WORK/approval-$p.json" raw_state)"
    case "$stage" in
      live) part "$p" "{\"result\": \"$([ "$p" = ios ] && echo released || echo published)\", \"raw_state\": \"$state\"}"; continue;;
      in_progress) part "$p" "{\"result\": \"pending\", \"raw_state\": \"$state\"}"; continue;;
    esac
    res="$WORK/action-$p.json"; rc=0
    if [ "$p" = ios ]; then store_ios_release "$(name_for ios)" "$CONFIRM" >"$res" || rc=$?
    else store_android_publish "$(name_for android)" "$CONFIRM" >"$res" || rc=$?; fi
    if [ "$rc" != 0 ] || ! python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); assert isinstance(d.get("result"), str)' "$res" 2>/dev/null; then
      part "$p" "{\"result\": \"failed\", \"raw_state\": null, \"reason\": \"hook_exit_$rc\"}"; continue
    fi
    part "$p" "$(python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); print(json.dumps({"result": d["result"], "raw_state": d.get("raw_state")}))' "$res")"
    if [ "$(jget "$res" result)" = needs_login ]; then
      # 사람이 할 일 — rcm 이 요청한 세션과 화면에 알린다. 다음 시도가 다시 확인한다.
      echo "::rcm::action::login::Play Console sign-in expired on the build machine - sign in to its Chrome profile by screen sharing, or publish from your own Chrome"
    fi
  done
  for p in $(platforms); do
    results+=("$p=$(jget "$WORK/golive-$p.part.json" result)")
    case "$(jget "$WORK/golive-$p.part.json" result)" in
      failed) overall=1;;
      released|published) ;;
      *) [ "$overall" = 1 ] || overall=75;;
    esac
  done
  if [ "$overall" = 0 ]; then step_end ok; else step_end fail; fi
  write_golive_doc "$overall" || { finish "failed — golive.json violates the contract (see log); check the stores by hand" 1; }
  case "$overall" in
    0)  finish "live — ${results[*]}" 0;;
    75) finish "not yet — ${results[*]} (approved; the next attempt checks again)" 75;;
    *)  finish "failed — ${results[*]}; check the stores by hand" 1;;
  esac
}

main() {
  case "$MODE" in plan|release) ;; *) echo "RCM_INPUT_MODE must be plan|release, got '$MODE'" >&2; usage;; esac
  case "$PLATFORM" in ios|android|both) ;; *) echo "RCM_INPUT_PLATFORM must be ios|android|both, got '$PLATFORM'" >&2; usage;; esac
  [[ "$BUILD_NAME" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "RCM_INPUT_BUILD_NAME must be X.Y.Z, got '$BUILD_NAME'" >&2; usage; }
  [ -z "$BUILD_NAME_ANDROID" ] || [[ "$BUILD_NAME_ANDROID" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "RCM_INPUT_BUILD_NAME_ANDROID must be X.Y.Z, got '$BUILD_NAME_ANDROID'" >&2; usage; }
  if [ "$MODE" = release ] && ! [[ "$CONFIRM" =~ ^[0-9]+$ ]]; then echo "mode=release needs RCM_INPUT_CONFIRM_BUILD_NUMBER (the number a person typed)" >&2; usage; fi
  [ -f "$CONTRACT" ] || { echo "missing $CONTRACT — reinstall with /rcm-store-connect" >&2; exit 2; }
  mkdir -p "$WORK"; rm -f "$WORK"/golive-*.part.json "$WORK"/approval-*.json
  echo "::rcm::steps::4"

  step "preflight"
  if [ -z "$SECRETS_DIR" ] || [ ! -d "$SECRETS_DIR" ]; then
    step_end fail
    finish "BLOCKED(env) — secrets folder missing (\$$SECRETS_ENV)" 2
  fi
  step_end ok
  STARTED=1
  if [ "$MODE" = plan ]; then do_plan; else do_release; fi
}

# ── selftest ─────────────────────────────────────────────────────────────────────────────────────────
selftest() {
  local t rc fails=0
  t="$(mktemp -d)"; mkdir -p "$t/secrets"
  check() {  # $1 label · $2 expected rc · $3 actual · $4 file · $5 assertion ('' = skip) · $6 expected release-call count
    if [ "$2" != "$3" ]; then echo "FAIL $1: exit $3, expected $2"; cat "$t/out"; fails=$((fails+1)); return; fi
    if [ -n "$5" ] && ! python3 -c "import json,sys; d=json.load(open(sys.argv[1])); assert $5, d" "$t/work/$4"; then
      echo "FAIL $1: $4 assertion failed: $5"; fails=$((fails+1)); return
    fi
    local calls; calls="$(grep -cE '^store_(ios_release|android_publish)' "$t/calls" 2>/dev/null || true)"; calls="${calls:-0}"
    if [ "$6" != "$calls" ]; then echo "FAIL $1: release hooks called $calls times, expected $6"; fails=$((fails+1)); return; fi
    echo "  ok  $1"
  }
  run() {  # env assignments
    rm -rf "$t/work" "$t/calls"; mkdir -p "$t/work"; rc=0
    env RELEASE_SHIM=1 RELEASE_SHIM_CALLS="$t/calls" RELEASE_WORK="$t/work" RCM_INPUT_BUILD_NAME=1.2.0 \
        "$SECRETS_ENV=$t/secrets" "$@" bash "$SELF" >"$t/out" 2>&1 || rc=$?
  }
  echo "[release_golive] selftest ($SECRETS_ENV)"
  # plan — 읽었으면 0, 승인은 문서에만(결정 224)
  run RELEASE_SHIM_IOS=waiting RELEASE_SHIM_ANDROID=in_review
  check "plan, Android not approved -> exit 0, android.approved = false" 0 "$rc" golive-plan.json "d['platforms']['ios']['approved'] is True and d['platforms']['ios']['approved_build']==185 and d['platforms']['android']['approved'] is False and d['plan_verdict']=='blocked' and 'android_not_approved' in d['reasons']" 0
  [ ! -e "$t/work/golive.json" ] || { echo "FAIL plan wrote golive.json"; fails=$((fails+1)); }
  run RCM_INPUT_MODE=plan RELEASE_SHIM_IOS=waiting RELEASE_SHIM_ANDROID=waiting
  check "plan, both approved -> exit 0, plan_verdict ok" 0 "$rc" golive-plan.json "d['plan_verdict']=='ok' and d['reasons']==[]" 0
  run RCM_INPUT_PLATFORM=ios RELEASE_SHIM_IOS=waiting RELEASE_SHIM_ANDROID=unreadable
  check "plan ios only -> Android is not read" 0 "$rc" golive-plan.json "list(d['platforms'])==['ios'] and d['plan_verdict']=='ok'" 0
  run RELEASE_SHIM_IOS=waiting RELEASE_SHIM_ANDROID=unreadable
  check "plan, store unreadable -> exit 1, golive-plan.json still written" 1 "$rc" golive-plan.json "d['platforms']['android']['raw_state'] is None and 'android_unreadable' in d['reasons']" 0
  # release — 미승인은 언제나 2(결정 236)
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=ios RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_IOS=in_review
  check "release, not approved -> exit 2 (never 75), no release call" 2 "$rc" golive.json "d['platforms']['ios']['result']=='failed' and d['platforms']['ios']['reason']=='not_approved'" 0
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=both RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_IOS=waiting RELEASE_SHIM_ANDROID=in_review
  check "release both, Android not approved -> exit 2, iOS untouched too" 2 "$rc" golive.json "d['platforms']['android']['reason']=='not_approved' and d['platforms']['ios']['reason']=='not_attempted'" 0
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=ios RCM_INPUT_CONFIRM_BUILD_NUMBER=184 RELEASE_SHIM_IOS=waiting
  check "release, build number mismatch -> exit 3, no release call" 3 "$rc" golive.json "d['platforms']['ios']['reason']=='build_number_mismatch' and d['platforms']['ios']['approved_build']==185" 0
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=both RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_ANDROID_BUILD=186
  check "release both, the two approved builds differ -> exit 3, no release call" 3 "$rc" golive.json "d['platforms']['android']['reason']=='build_number_mismatch'" 0
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=ios RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_IOS=unreadable
  check "release, store unreadable -> exit 1, no release call" 1 "$rc" golive.json "d['platforms']['ios']['reason']=='unreadable'" 0
  # release — 승인 뒤 남은 일만 75
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=ios RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_IOS=waiting
  check "release ios, approved -> release requested, exit 75 until the store says live" 75 "$rc" golive.json "d['platforms']['ios']['result']=='requested' and d['exit_code']==75" 1
  grep -q "^store_ios_release '1.2.0' '185'" "$t/calls" || { echo "FAIL the iOS hook got the wrong version or build"; fails=$((fails+1)); }
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=ios RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_IOS=in_progress
  check "release ios, release processing -> exit 75, no second call" 75 "$rc" golive.json "d['platforms']['ios']['result']=='pending'" 0
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=ios RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_IOS=live
  check "release ios, already live -> exit 0, no release call" 0 "$rc" golive.json "d['platforms']['ios']['result']=='released'" 0
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=android RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_ANDROID=in_progress
  check "release android, publish pressed, not live yet -> exit 75, no second publish" 75 "$rc" golive.json "d['platforms']['android']['result']=='pending'" 0
  local t0=$SECONDS
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=android RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RCM_INPUT_BUILD_NAME_ANDROID=1.0.9 RELEASE_SHIM_ANDROID_ACTION=needs_login
  check "release, login lost -> action marker + exit 75" 75 "$rc" golive.json "d['platforms']['android']['result']=='needs_login'" 1
  # 표식을 찍으면 그 자리에서 끝난다 — 승인을 다시 읽거나 게시를 다시 누르며 기다리지 않는다
  if [ "$(grep -c '^store_approval ' "$t/calls")" = 1 ] && [ "$(grep -c '^store_android_publish ' "$t/calls")" = 1 ] \
     && [ $((SECONDS - t0)) -lt 10 ] && [[ "$(tail -n 1 "$t/out")" == "::rcm::summary::not yet"* ]]; then
    echo "  ok  release, login lost -> exits 75 at once: one read, one publish, no wait"
  else
    echo "FAIL login lost: the script read or pressed again, or waited ($((SECONDS - t0))s)"; cat "$t/calls"; fails=$((fails+1))
  fi
  grep -q '^::rcm::action::login::' "$t/out" || { echo "FAIL no ::rcm::action::login:: marker"; fails=$((fails+1)); }
  grep -q "^store_android_publish '1.0.9' '185'" "$t/calls" || { echo "FAIL the Android hook did not get the Android name"; fails=$((fails+1)); }
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=android RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_ANDROID_ACTION=published
  check "release android, published -> exit 0" 0 "$rc" golive.json "d['platforms']['android']['result']=='published'" 1
  grep -q '::rcm::action::' "$t/out" && { echo "FAIL an action marker without a lost sign-in"; fails=$((fails+1)); }
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=android RCM_INPUT_CONFIRM_BUILD_NUMBER=185 RELEASE_SHIM_ANDROID_ACTION=fail
  check "release android, the publish hook fails -> exit 1" 1 "$rc" golive.json "d['platforms']['android']['result']=='failed'" 1
  # 사용법 · 환경
  run RCM_INPUT_MODE=release RCM_INPUT_PLATFORM=ios
  check "release without a typed build number -> usage exit 2, no store call" 2 "$rc" "" "" 0
  [ ! -s "$t/calls" ] || { echo "FAIL the store was read without a typed number"; fails=$((fails+1)); }
  run RCM_INPUT_MODE=release RCM_INPUT_CONFIRM_BUILD_NUMBER=185 "$SECRETS_ENV=$t/none"
  check "release without secrets -> exit 2, store untouched" 2 "$rc" "" "" 0
  run RCM_INPUT_MODE=publish;     check "unknown mode -> usage exit 2" 2 "$rc" "" "" 0
  run RCM_INPUT_BUILD_NAME=1.2;   check "bad build name -> usage exit 2" 2 "$rc" "" "" 0
  rm -rf "$t"
  [ "$fails" = 0 ] && { echo "[release_golive] selftest PASS — plan reads and exits 0, release never waits for an approval, the typed number must match"; return 0; }
  echo "[release_golive] selftest FAIL ($fails)"; return 1
}

case "${1:-}" in --selftest) WRITTEN=1; selftest;; "") main;; *) usage;; esac
